content:
:root {
  --color-bg-base: #12141a;
  --color-bg-surface: #1a1e27;
  --color-bg-elevated: #242a38;
  --color-border: #333c4f;
  --color-border-focus: #5d6d88;
  --color-text-main: #f1f5f9;
  --color-text-muted: #94a3b8;
  --color-text-dim: #64748b;

  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-glow: rgba(59, 130, 246, 0.35);
  --color-accent-felt: #b91c1c;
  --color-accent-amber: #f59e0b;

  --shadow-key-white: 0 4px 6px -1px rgba(0, 0, 0, 0.25), 0 2px 4px -2px rgba(0, 0, 0, 0.2), inset 0 -3px 0 #cbd5e1, inset 0 1px 0 #ffffff;
  --shadow-key-white-active: 0 1px 2px rgba(0, 0, 0, 0.3), inset 0 2px 4px rgba(0, 0, 0, 0.15), inset 0 -1px 0 #94a3b8;
  --shadow-key-black: 0 6px 10px rgba(0, 0, 0, 0.45), inset 0 -4px 0 #0f172a, inset 0 1px 1px rgba(255, 255, 255, 0.25);
  --shadow-key-black-active: 0 2px 4px rgba(0, 0, 0, 0.5), inset 0 2px 4px rgba(0, 0, 0, 0.6), inset 0 -1px 0 #020617;

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-family);
  background-color: var(--color-bg-base);
  color: var(--color-text-main);
  min-height: 100vh;
  line-height: 1.5;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ピアノアプリ全体のコンテナ */
.piano-app {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 100vh;
  padding: 1.5rem 1rem 3rem;
  background: radial-gradient(circle at 50% 20%, #1e2536 0%, var(--color-bg-base) 80%);
}

/* ヘッダー */
.piano-header {
  text-align: center;
  margin-bottom: 1.5rem;
  max-width: 760px;
  width: 100%;
}

.piano-header-title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #ffffff 40%, #93c5fd 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.35rem;
}

.piano-header-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* メインステージ */
.piano-main {
  width: 100%;
  max-width: 900px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* 操作パネルコンテナ */
.controls-container {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
  align-items: center;
  justify-content: space-between;
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  min-width: 130px;
}

.control-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
}

/* フォーム部品 */
.select-input {
  background-color: var(--color-bg-elevated);
  color: var(--color-text-main);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.select-input:hover,
.select-input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-primary-glow);
}

.range-slider {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  background: var(--color-bg-elevated);
  outline: none;
  cursor: pointer;
}

.range-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--color-primary);
  cursor: pointer;
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.5);
  transition: transform 0.1s ease;
}

.range-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

.range-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--color-primary);
  border: none;
  cursor: pointer;
}

/* ボタン群 */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border);
  background-color: var(--color-bg-elevated);
  color: var(--color-text-main);
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.btn:hover {
  background-color: #2c3445;
  border-color: var(--color-border-focus);
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  color: #ffffff;
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
  border-color: var(--color-primary-hover);
}

.btn-demo {
  background-color: rgba(245, 158, 11, 0.1);
  border-color: rgba(245, 158, 11, 0.3);
  color: #fbbf24;
}

.btn-demo:hover {
  background-color: rgba(245, 158, 11, 0.2);
  border-color: var(--color-accent-amber);
}

.btn-active {
  background-color: var(--color-primary);
  border-color: var(--color-primary);
  color: #ffffff;
  box-shadow: 0 0 10px var(--color-primary-glow);
}

/* 演奏ステージ＆表示部 */
.piano-stage {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  background-color: #0b0d13;
  padding: 1.5rem 1.5rem 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid #1e2433;
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.6), 0 20px 30px -10px rgba(0, 0, 0, 0.5);
}

.playing-display {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1.25rem;
  background-color: #161922;
  border: 1px solid #232a3b;
  border-radius: var(--radius-md);
  min-height: 48px;
}

.current-note-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.2), rgba(147, 197, 253, 0.1));
  border: 1px solid rgba(59, 130, 246, 0.4);
  color: #93c5fd;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-weight: 700;
  font-size: 0.875rem;
  animation: pulse-glow 1.5s infinite;
}

@keyframes pulse-glow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

/* 鍵盤全体ラッパー */
.keyboard-wrapper {
  position: relative;
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  padding: 18px 12px 12px;
  background: linear-gradient(to bottom, #11141a 0%, #0d0f14 100%);
  border-radius: var(--radius-md);
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

/* ピアノの赤いフェルト部（鍵盤の根元） */
.keyboard-wrapper::before {
  content: "";
  position: absolute;
  top: 10px;
  left: 12px;
  right: 12px;
  height: 8px;
  background: var(--color-accent-felt);
  border-radius: 2px 2px 0 0;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.5), 0 2px 4px rgba(185, 28, 28, 0.3);
  z-index: 5;
}

/* 鍵盤配置コンテナ */
.piano-keys-container {
  position: relative;
  display: flex;
  width: 100%;
  height: 240px;
  user-select: none;
  touch-action: none;
}

.white-keys-container {
  display: flex;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.black-keys-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 60%;
  pointer-events: none;
  z-index: 2;
}

/* 鍵盤共通 */
.piano-key {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 0.75rem;
  cursor: pointer;
  user-select: none;
  transition: transform 0.06s ease, background-color 0.08s ease, box-shadow 0.06s ease;
}

/* 白鍵（8鍵：C4〜C5） */
.white-key {
  flex: 1;
  height: 100%;
  background: linear-gradient(to bottom, #fcfcfc 0%, #f1f5f9 85%, #e2e8f0 100%);
  border: 1px solid #94a3b8;
  border-top: none;
  border-radius: 0 0 6px 6px;
  box-shadow: var(--shadow-key-white);
  color: #1e293b;
  margin: 0 1px;
}

.white-key:first-child {
  border-bottom-left-radius: 8px;
}

.white-key:last-child {
  border-bottom-right-radius: 8px;
}

.white-key.key-active {
  background: linear-gradient(to bottom, #dbeafe 0%, #bfdbfe 85%, #93c5fd 100%);
  box-shadow: var(--shadow-key-white-active), 0 0 12px rgba(59, 130, 246, 0.4);
  transform: translateY(3px);
  border-color: #60a5fa;
}

/* 黒鍵（5鍵：C#4, D#4, F#4, G#4, A#4） */
.black-key {
  pointer-events: auto;
  position: absolute;
  width: 7.2%;
  height: 100%;
  background: linear-gradient(to bottom, #262a34 0%, #171920 70%, #0a0b0e 100%);
  border: 1px solid #000000;
  border-top: none;
  border-radius: 0 0 4px 4px;
  box-shadow: var(--shadow-key-black);
  color: #e2e8f0;
  padding-bottom: 0.5rem;
}

/* 黒鍵の精密な位置オフセット（白鍵8鍵幅を100%とした場合の配置） */
.black-key[data-note="C#4"],
.black-key[data-note="Db4"] {
  left: 8.9%;
}

.black-key[data-note="D#4"],
.black-key[data-note="Eb4"] {
  left: 21.4%;
}

.black-key[data-note="F#4"],
.black-key[data-note="Gb4"] {
  left: 46.4%;
}

.black-key[data-note="G#4"],
.black-key[data-note="Ab4"] {
  left: 58.9%;
}

.black-key[data-note="A#4"],
.black-key[data-note="Bb4"] {
  left: 71.4%;
}

.black-key.key-active {
  background: linear-gradient(to bottom, #1d4ed8 0%, #1e40af 70%, #172554 100%);
  box-shadow: var(--shadow-key-black-active), 0 0 14px rgba(59, 130, 246, 0.6);
  transform: translateY(3px);
  border-color: #3b82f6;
}

/* 鍵盤上の表示要素 */
.key-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  pointer-events: none;
}

.key-name {
  font-size: 0.875rem;
  font-weight: 700;
}

.white-key .key-name {
  color: #334155;
}

.white-key.key-active .key-name {
  color: #1d4ed8;
}

.black-key .key-name {
  font-size: 0.75rem;
  color: #94a3b8;
}

.black-key.key-active .key-name {
  color: #bfdbfe;
}

.key-hint {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 4px;
}

.white-key .key-hint {
  color: #64748b;
  background-color: #e2e8f0;
}

.white-key.key-active .key-hint {
  background-color: #bfdbfe;
  color: #1e3a8a;
}

.black-key .key-hint {
  color: #cbd5e1;
  background-color: #334155;
}

.black-key.key-active .key-hint {
  background-color: #2563eb;
  color: #ffffff;
}

/* デモ演奏パネル */
.demo-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1rem 1.25rem;
}

/* 説明・ヘルプカード */
.instructions-card {
  background-color: var(--color-bg-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.25rem 1.5rem;
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

.instructions-card h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text-main);
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.instructions-card ul {
  padding-left: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.instructions-card kbd {
  display: inline-block;
  padding: 0.1rem 0.4rem;
  font-size: 0.75rem;
  font-family: inherit;
  font-weight: 600;
  background-color: var(--color-bg-elevated);
  border: 1px solid var(--color-border-focus);
  border-radius: 4px;
  color: #cbd5e1;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.4);
}

/* レスポンシブ対応 */
@media (max-width: 640px) {
  .piano-app {
    padding: 1rem 0.5rem 2rem;
  }

  .piano-header-title {
    font-size: 1.6rem;
  }

  .controls-container {
    padding: 1rem;
    gap: 0.875rem;
  }

  .control-group {
    min-width: calc(50% - 0.5rem);
  }

  .piano-stage {
    padding: 1rem 0.75rem 1.25rem;
  }

  .keyboard-wrapper {
    padding: 14px 6px 8px;
  }

  .keyboard-wrapper::before {
    left: 6px;
    right: 6px;
    height: 6px;
    top: 8px;
  }

  .piano-keys-container {
    height: 180px;
  }

  .black-key {
    height: 58%;
    padding-bottom: 0.25rem;
  }

  .white-key {
    padding-bottom: 0.4rem;
  }

  .key-name {
    font-size: 0.75rem;
  }

  .black-key .key-name {
    font-size: 0.65rem;
  }

  .key-hint {
    display: none;
  }
}

export type WaveformType = 'triangle' | 'sine' | 'square' | 'sawtooth';

export interface SoundInstrument {
  id: string;
  name: string;
  type: WaveformType;
  attack: number;
  decay: number;
  sustain: number;
  release: number;
}

export interface PianoKey {
  note: string;
  pitch: string;
  freq: number;
  isBlack: boolean;
  keyboardKey: string;
  labelJa: string;
}

export interface DemoNote {
  pitch: string;
  duration: number;
}

export interface DemoSong {
  title: string;
  notes: DemoNote[];
}

export type LabelDisplayMode = 'ja' | 'en' | 'key';

import { SoundInstrument, PianoKey, DemoSong } from '../types';

let audioCtx: AudioContext | null = null;

export const getAudioContext = (): AudioContext => {
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    audioCtx = new AudioContextClass();
  }
  if (audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
  return audioCtx;
};

