// オクターブ計算ユーティリティ（オクターブシフト: -1, 0, +1）
export const calculateFrequency = (baseFreq: number, octaveShift: number): number => {
  return baseFreq * Math.pow(2, octaveShift);
};

// 単音の再生関数（Web Audio APIシンセシス、音の停止関数を返す）
export const playTone = (
  freq: number,
  instrument: SoundInstrument,
  volume = 0.5
): (() => void) => {
  const ctx = getAudioContext();
  const now = ctx.currentTime;

  // オシレーターの初期化
  const osc = ctx.createOscillator();
  osc.type = instrument.type;
  osc.frequency.setValueAtTime(freq, now);

  // ゲインノード（ADSRエンベロープ）
  const gainNode = ctx.createGain();
  const safeVolume = Math.max(0.001, Math.min(volume, 1.0));

  // アタック (0 -> peak)
  gainNode.gain.setValueAtTime(0.0001, now);
  gainNode.gain.linearRampToValueAtTime(safeVolume, now + instrument.attack);

  // ディケイ & サステイン (peak -> sustain)
  const sustainLevel = Math.max(0.0001, safeVolume * instrument.sustain);
  gainNode.gain.exponentialRampToValueAtTime(
    sustainLevel,
    now + instrument.attack + instrument.decay
  );

  osc.connect(gainNode);
  gainNode.connect(ctx.destination);
  osc.start(now);

  let isStopped = false;

  // 停止関数（リリースエンベロープ適用）
  return () => {
    if (isStopped) return;
    isStopped = true;

    const stopTime = ctx.currentTime;
    gainNode.gain.cancelScheduledValues(stopTime);
    gainNode.gain.setValueAtTime(gainNode.gain.value, stopTime);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, stopTime + instrument.release);

    setTimeout(() => {
      try {
        osc.stop();
        osc.disconnect();
        gainNode.disconnect();
      } catch {
        // すでに解放済みの場合は無視
      }
    }, instrument.release * 1000 + 50);
  };
};

