import { ChangeEvent } from 'react';
import { SoundInstrument, LabelDisplayMode, DemoSong } from '../types';
import { INSTRUMENTS, DEMO_SONGS } from '../utils/audio';

interface ControlsProps {
  currentInstrument: SoundInstrument;
  onInstrumentChange: (instrument: SoundInstrument) => void;
  octaveShift: number;
  onOctaveShiftChange: (shift: number) => void;
  volume: number;
  onVolumeChange: (volume: number) => void;
  labelMode: LabelDisplayMode;
  onLabelModeChange: (mode: LabelDisplayMode) => void;
  isPlayingDemo: boolean;
  currentDemoSongTitle: string | null;
  onPlayDemo: (song: DemoSong) => void;
  onStopDemo: () => void;
}

const Controls = ({
  currentInstrument,
  onInstrumentChange,
  octaveShift = 0,
  onOctaveShiftChange,
  volume = 0.5,
  onVolumeChange,
  labelMode = 'ja',
  onLabelModeChange,
  isPlayingDemo = false,
  currentDemoSongTitle = null,
  onPlayDemo,
  onStopDemo,
}: ControlsProps) => {
  const handleInstrumentSelect = (e: ChangeEvent<HTMLSelectElement>) => {
    const selected = INSTRUMENTS.find((inst) => inst.id === e.target.value);
    if (selected) {
      onInstrumentChange?.(selected);
    }
  };

  const handleVolumeInput = (e: ChangeEvent<HTMLInputElement>) => {
    onVolumeChange?.(parseFloat(e.target.value));
  };

  const handleLabelModeSelect = (e: ChangeEvent<HTMLSelectElement>) => {
    onLabelModeChange?.(e.target.value as LabelDisplayMode);
  };

  return (
    <div className="controls-container">
      {/* 音色切替 */}
      <div className="control-group">
        <label className="control-label" htmlFor="instrument-select">音色</label>
        <select
          id="instrument-select"
          className="select-input"
          value={currentInstrument.id}
          onChange={handleInstrumentSelect}
          disabled={isPlayingDemo}
        >
          {INSTRUMENTS.map((inst) => (
            <option key={inst.id} value={inst.id}>
              {inst.name}
            </option>
          ))}
        </select>
      </div>

      {/* オクターブ変更 */}
      <div className="control-group">
        <span className="control-label">オクターブ ({octaveShift > 0 ? `+${octaveShift}` : octaveShift})</span>
        <div style={{ display: 'flex', gap: '0.35rem' }}>
          <button
            type="button"
            className={`btn ${octaveShift === -1 ? 'btn-active' : ''}`}
            onClick={() => onOctaveShiftChange?.(-1)}
            disabled={isPlayingDemo}
            title="1オクターブ低く"
          >
            -1
          </button>
          <button
            type="button"
            className={`btn ${octaveShift === 0 ? 'btn-active' : ''}`}
            onClick={() => onOctaveShiftChange?.(0)}
            disabled={isPlayingDemo}
            title="標準"
          >
            標準
          </button>
          <button
            type="button"
            className={`btn ${octaveShift === 1 ? 'btn-active' : ''}`}
            onClick={() => onOctaveShiftChange?.(1)}
            disabled={isPlayingDemo}
            title="1オクターブ高く"
          >
            +1
          </button>
        </div>
      </div>

      {/* 音量バー */}
      <div className="control-group">
        <label className="control-label" htmlFor="volume-slider">
          音量 ({Math.round(volume * 100)}%)
        </label>
        <input
          id="volume-slider"
          type="range"
          min="0.05"
          max="1"
          step="0.05"
          value={volume}
          onChange={handleVolumeInput}
          className="range-slider"
        />
      </div>

      {/* 鍵盤表示切替 */}
      <div className="control-group">
        <label className="control-label" htmlFor="label-mode-select">鍵盤ラベル</label>
        <select
          id="label-mode-select"
          className="select-input"
          value={labelMode}
          onChange={handleLabelModeSelect}
        >
          <option value="ja">ドレミ (日本語)</option>
          <option value="en">C D E (音名)</option>
          <option value="key">PCキー (A W S...)</option>
        </select>
      </div>

      {/* デモ演奏 */}
      <div className="control-group" style={{ minWidth: '180px' }}>
        <span className="control-label">デモソング自動演奏</span>
        <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
          {DEMO_SONGS.map((song) => {
            const isThisPlaying = isPlayingDemo && currentDemoSongTitle === song.title;
            return (
              <button
                key={song.title}
                type="button"
                className={`btn btn-demo ${isThisPlaying ? 'btn-active' : ''}`}
                onClick={() => {
                  if (isThisPlaying) {
                    onStopDemo?.();
                  } else {
                    onPlayDemo?.(song);
                  }
                }}
              >
                {isThisPlaying ? `⏹ ${song.title}` : `▶ ${song.title}`}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default Controls;

import { PianoKey, LabelDisplayMode } from '../types';
import { WHITE_KEYS, BLACK_KEYS } from '../utils/audio';

interface PianoKeyboardProps {
  activeNotes?: string[];
  labelMode?: LabelDisplayMode;
  onNotePress?: (key: PianoKey) => void;
  onNoteRelease?: (key: PianoKey) => void;
}

const PianoKeyboard = ({
  activeNotes = [],
  labelMode = 'ja',
  onNotePress,
  onNoteRelease,
}: PianoKeyboardProps) => {
  const getDisplayLabel = (key: PianoKey): string => {
    switch (labelMode) {
      case 'ja':
        return key.labelJa;
      case 'en':
        return key.pitch;
      case 'key':
        return key.keyboardKey.toUpperCase();
      default:
        return key.labelJa;
    }
  };

  const isNoteActive = (pitch: string): boolean => {
    return activeNotes.includes(pitch);
  };

  return (
    <div className="keyboard-wrapper">
      <div className="piano-keys-container">
        {/* 白鍵群 (8鍵) */}
        <div className="white-keys-container">
          {WHITE_KEYS.map((key) => {
            const active = isNoteActive(key.pitch);
            return (
              <div
                key={key.pitch}
                className={`piano-key white-key ${active ? 'key-active' : ''}`}
                onPointerDown={(e) => {
                  e.preventDefault();
                  onNotePress?.(key);
                }}
                onPointerUp={(e) => {
                  e.preventDefault();
                  onNoteRelease?.(key);
                }}
                onPointerLeave={() => {
                  if (active) {
                    onNoteRelease?.(key);
                  }
                }}
                onPointerCancel={() => {
                  if (active) {
                    onNoteRelease?.(key);
                  }
                }}
              >
                <div className="key-label">
                  <span className="key-name">{getDisplayLabel(key)}</span>
                  <span className="key-hint">{key.keyboardKey.toUpperCase()}</span>
                </div>
              </div>
            );
          })}
        </div>

        {/* 黒鍵群 (5鍵) */}
        <div className="black-keys-container">
          {BLACK_KEYS.map((key) => {
            const active = isNoteActive(key.pitch);
            return (
              <div
                key={key.pitch}
                data-note={key.pitch}
                className={`piano-key black-key ${active ? 'key-active' : ''}`}
                onPointerDown={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  onNotePress?.(key);
                }}
                onPointerUp={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  onNoteRelease?.(key);
                }}
                onPointerLeave={() => {
                  if (active) {
                    onNoteRelease?.(key);
                  }
                }}
                onPointerCancel={() => {
                  if (active) {
                    onNoteRelease?.(key);
                  }
                }}
              >
                <div className="key-label">
                  <span className="key-name">{getDisplayLabel(key)}</span>
                  <span className="key-hint">{key.keyboardKey.toUpperCase()}</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default PianoKeyboard;

import { useState, useEffect, useRef, useCallback } from 'react';
import {
  SoundInstrument,
  PianoKey,
  LabelDisplayMode,
  DemoSong,
} from './types';
import {
  INSTRUMENTS,
  PIANO_KEYS,
  playTone,
  calculateFrequency,
  getAudioContext,
} from './utils/audio';
import Controls from './components/Controls';
import PianoKeyboard from './components/PianoKeyboard';
import './index.css';

const App = () => {
  const [currentInstrument, setCurrentInstrument] = useState<SoundInstrument>(INSTRUMENTS[0]);
  const [octaveShift, setOctaveShift] = useState<number>(0);
  const [volume, setVolume] = useState<number>(0.6);
  const [labelMode, setLabelMode] = useState<LabelDisplayMode>('ja');
  const [activeNotes, setActiveNotes] = useState<string[]>([]);
  const [lastPlayedNoteText, setLastPlayedNoteText] = useState<string>('まだ演奏していません');
  const [isPlayingDemo, setIsPlayingDemo] = useState<boolean>(false);
  const [currentDemoSongTitle, setCurrentDemoSongTitle] = useState<string | null>(null);

  // 鍵盤毎のアクティブな停止関数を保持する参照
  const stopToneMapRef = useRef<Map<string, () => void>>(new Map());
  // デモ再生用タイマー配列の参照
  const demoTimersRef = useRef<number[]>([]);

  // 音を鳴らす処理
  const handleStartTone = useCallback(
    (key: PianoKey) => {
      // 既に発音中なら一度停止
      const existingStop = stopToneMapRef.current.get(key.pitch);
      if (existingStop) {
        existingStop();
        stopToneMapRef.current.delete(key.pitch);
      }

      const freq = calculateFrequency(key.freq, octaveShift);
      const stopFn = playTone(freq, currentInstrument, volume);
      stopToneMapRef.current.set(key.pitch, stopFn);

      setActiveNotes((prev) => (prev.includes(key.pitch) ? prev : [...prev, key.pitch]));

      const octaveDisplay = octaveShift === 0 ? '' : octaveShift > 0 ? ` (+${octaveShift})` : ` (${octaveShift})`;
      setLastPlayedNoteText(`${key.labelJa} (${key.pitch}${octaveDisplay})`);
    },
    [currentInstrument, octaveShift, volume]
  );

  // 音を止める処理
  const handleStopTone = useCallback((key: PianoKey) => {
    const stopFn = stopToneMapRef.current.get(key.pitch);
    if (stopFn) {
      stopFn();
      stopToneMapRef.current.delete(key.pitch);
    }
    setActiveNotes((prev) => prev.filter((p) => p !== key.pitch));
  }, []);

  // すべての音を停止
  const stopAllNotes = useCallback(() => {
    stopToneMapRef.current.forEach((stopFn) => {
      try {
        stopFn();
      } catch {
        // 解放済みエラー防止
      }
    });
    stopToneMapRef.current.clear();
    setActiveNotes([]);
  }, []);

  // デモ停止処理
  const handleStopDemo = useCallback(() => {
    demoTimersRef.current.forEach((id) => window.clearTimeout(id));
    demoTimersRef.current = [];
    stopAllNotes();
    setIsPlayingDemo(false);
    setCurrentDemoSongTitle(null);
  }, [stopAllNotes]);

  // デモ曲自動演奏処理
  const handlePlayDemo = useCallback(
    (song: DemoSong) => {
      // 既存の再生をリセット
      handleStopDemo();
      getAudioContext();

      setIsPlayingDemo(true);
      setCurrentDemoSongTitle(song.title);

      let accumulatedDelay = 50;

      song.notes.forEach((item, index) => {
        const targetKey = PIANO_KEYS.find((k) => k.pitch === item.pitch);
        if (!targetKey) return;

        // ノートONタイマー
        const onTimer = window.setTimeout(() => {
          handleStartTone(targetKey);
        }, accumulatedDelay);
        demoTimersRef.current.push(onTimer);

        // ノートOFFタイマー（発音時間よりわずかに手前で離す）
        const playDuration = Math.max(80, item.duration - 70);
        const offTimer = window.setTimeout(() => {
          handleStopTone(targetKey);
        }, accumulatedDelay + playDuration);
        demoTimersRef.current.push(offTimer);

        accumulatedDelay += item.duration;

        // 最後のノート終了時にデモ再生を完了
        if (index === song.notes.length - 1) {
          const finishTimer = window.setTimeout(() => {
            setIsPlayingDemo(false);
            setCurrentDemoSongTitle(null);
          }, accumulatedDelay + 200);
          demoTimersRef.current.push(finishTimer);
        }
      });
    },
    [handleStartTone, handleStopTone, handleStopDemo]
  );

  // PCキーボード入力対応
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      if (isPlayingDemo) return;

      const keyChar = e.key.toLowerCase();
      const matchedKey = PIANO_KEYS.find((k) => k.keyboardKey === keyChar);
      if (matchedKey) {
        getAudioContext();
        handleStartTone(matchedKey);
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      const keyChar = e.key.toLowerCase();
      const matchedKey = PIANO_KEYS.find((k) => k.keyboardKey === keyChar);
      if (matchedKey) {
        handleStopTone(matchedKey);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [handleStartTone, handleStopTone, isPlayingDemo]);

  // クリーンアップ
  useEffect(() => {
    return () => {
      demoTimersRef.current.forEach((id) => window.clearTimeout(id));
      stopAllNotes();
    };
  }, [stopAllNotes]);

  return (
    <div className="piano-app">
      {/* ヘッダー */}
      <header className="piano-header">
        <h1 className="piano-header-title">Web ピアノスタジオ</h1>
        <p className="piano-header-subtitle">
          Web Audio APIで奏でる1オクターブのリアルタイム演奏ピアノ（キーボード・タッチ対応）
        </p>
      </header>

      {/* メインステージ */}
      <main className="piano-main">
        {/* 操作・設定パネル */}
        <Controls
          currentInstrument={currentInstrument}
          onInstrumentChange={setCurrentInstrument}
          octaveShift={octaveShift}
          onOctaveShiftChange={setOctaveShift}
          volume={volume}
          onVolumeChange={setVolume}
          labelMode={labelMode}
          onLabelModeChange={setLabelMode}
          isPlayingDemo={isPlayingDemo}
          currentDemoSongTitle={currentDemoSongTitle}
          onPlayDemo={handlePlayDemo}
          onStopDemo={handleStopDemo}
        />

        {/* ピアノ本体ステージ */}
        <section className="piano-stage">
          {/* 現在の発音・情報ディスプレイ */}
          <div className="playing-display">
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <span style={{ fontSize: '0.85rem', color: 'var(--color-text-muted)' }}>
                直近の打鍵:
              </span>
              <span className="current-note-badge">
                {activeNotes.length > 0 ? `♪ 演奏中 (${activeNotes.join(', ')})` : lastPlayedNoteText}
              </span>
            </div>

            {isPlayingDemo && currentDemoSongTitle && (
              <span style={{ fontSize: '0.85rem', color: '#fbbf24', fontWeight: 600 }}>
                デモ再生中: {currentDemoSongTitle}
              </span>
            )}
          </div>

          {/* 鍵盤コンポーネント */}
          <PianoKeyboard
            activeNotes={activeNotes}
            labelMode={labelMode}
            onNotePress={(key) => {
              if (!isPlayingDemo) {
                getAudioContext();
                handleStartTone(key);
              }
            }}
            onNoteRelease={(key) => {
              if (!isPlayingDemo) {
                handleStopTone(key);
              }
            }}
          />
        </section>

        {/* 使い方・キー対応ガイド */}
        <aside className="instructions-card">
          <h3>🎹 演奏ガイド</h3>
          <ul>
            <li>
              <strong>PCキーボード操作:</strong>
              白鍵は <kbd>A</kbd>(ド), <kbd>S</kbd>(レ), <kbd>D</kbd>(ミ), <kbd>F</kbd>(ファ), <kbd>G</kbd>(ソ), <kbd>H</kbd>(ラ), <kbd>J</kbd>(シ), <kbd>K</kbd>(高いド)。
              黒鍵は <kbd>W</kbd>(ド#), <kbd>E</kbd>(レ#), <kbd>T</kbd>(ファ#), <kbd>Y</kbd>(ソ#), <kbd>U</kbd>(ラ#) で弾けます。
            </li>
            <li>
              <strong>スマホ・タブレット操作:</strong>
              画面上の白鍵・黒鍵をタップするだけで滑らかに演奏可能です。
            </li>
            <li>
              <strong>音色の変更:</strong>
              上のパネルから「ピアノ」「オルガン」「シンセ」「ビブラフォン」の4種類のリアルタイムシンセシスに即時切り替えができます。
            </li>
            <li>
              <strong>自動演奏デモ:</strong>
              「きらきら星」または「かえるの合唱」ボタンを押すと、鍵盤が光りながら自動演奏されます。
            </li>
          </ul>
        </aside>
      </main>
    </div>
  );
};

export default App;
